import{z as i,x as B,o as s,c as d,q as A,j as o,D as t,d as e,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"数据集存储与流式加载","description":"","frontmatter":{"title":"数据集存储与流式加载","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dataset-storage-streaming.md","filePath":"llm/dataset-storage-streaming.md","lastUpdated":1791413859000}'),p={name:"llm/dataset-storage-streaming.md"};function D(h,a,c,m,C,P){const r=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=A('<h1 id="数据集存储与流式加载" tabindex="-1">数据集存储与流式加载 <a class="header-anchor" href="#数据集存储与流式加载" aria-label="Permalink to &quot;数据集存储与流式加载&quot;">​</a></h1><div class="epigraph"><p>训练步若在等下一个 batch，集体通信再快也是空转。数据平面的屋顶线是「每秒解码多少 token」，不是模型 FLOPS。</p><footer>—— 对照 WebDataset / Mosaic Streaming / NVIDIA DALI 一类流式加载；突发 I/O 见检查点课</footer></div><p><a href="/llm/checkpoint-io-bandwidth">上一课</a> 写的是突发落盘。本课写持续的输入流：预训练语料在对象存储或分布式文件系统上，工人按 shuffle 顺序拉 shard、解码、组 batch。缺口是这条流如何与计算网、检查点共用集群，而不在 GPU 侧制造 <code>DataLoader</code> 空等。后课功率与冷却假定机器在算；本课先保证它有东西可算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语料以 TB 到 PB 计，不能每卡本地放全量。常见形状是许多 tar / parquet shard，每 rank 持一组，epoch 内打乱。墙有三层：存储吞吐（对象存储 GET 的 \\(\\beta\\)）、主机解码（压缩文本、图像、音视频 codec）、以及 PCIe 把 tensor 送进 GPU。LLM 文本解码相对轻，多模态 codec 可以比 GPU 还贵。小文件与随机读把存储拉进 \\(\\alpha\\) 区，和检查点的碎文件是同一类病。<span class="marginnote">术语翻译：\\(\\beta\\) 区指带宽主导的负载——大文件顺序读，能跑满网卡的每秒字节数上限；\\(\\alpha\\) 区指延迟主导的负载——每次读都要先等一轮「寻址 + 握手」的开销，文件越小、读得越碎，等待占比越高。一百万个 1 KB 小文件的处理时间，几乎全花在等待上而不是传输上。</span></p><p>shuffle 与确定性冲突：全局随机打乱需要协调或预打散；完全流式则各 rank 独立性好，但复现一次 epoch 更难。问题是 <strong>吞吐、打乱质量、复现</strong> 三选优先，而不是「用一个 DataLoader 默认值」。</p><p><span class="marginnote">缓存热 shard 到本地 NVMe 能把对象存储 \\(\\beta\\) 换成磁盘 \\(\\beta\\)，但会冻结打乱，并在作业换并行度时失效。适合反复扫同一子集的微调，不一定适合每天换包的预训练。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Shard 要大：单文件数百 MB 到数 GB，顺序读，内部再切样本。WebDataset 一类「tar 流」降低元数据；Mosaic Streaming 一类在索引里做确定性 shuffle。解码并行放在主机进程池，与 GPU 计算重叠；预取深度以填满 PCIe 与解码队列为准，过深则抢主机内存、和异步检查点打架。</p><p>网络上，数据拉流应走存储平面，与 NCCL 的计算网分开，理由与检查点相同。做不到则限速与 QoS，避免 epoch 开头所有 rank 同时打开第一批 shard 造成 incast——这是启动风暴，不是稳态 \\(\\beta\\)。</p>',10)),(s(),o(n,null,{default:t(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%20shard%22%5D%20--%3E%20PRE%5B%22%E9%A2%84%E5%8F%96%22%5D%0A%20%20PRE%20--%3E%20DEC%5B%22%E4%B8%BB%E6%9C%BA%E8%A7%A3%E7%A0%81%20%2F%20%E7%BB%84%20batch%22%5D%0A%20%20DEC%20--%3E%20GPU%5B%22H2D%22%5D%0A%20%20GPU%20--%3E%20STEP%5B%22%E8%AE%AD%E7%BB%83%E6%AD%A5%22%5D%0A%20%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E7%AA%81%E5%8F%91%22%5D%20-.-%3E%20OBJ%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"多模态：视觉 / 音频解码与文本 tokenize 分队列，避免图像 codec 堵住文本 batch。编码器若在 GPU 上，加载的是压缩比特流而不是已解码帧，把 codec 从 CPU 挪到 GPU 或专用管线，见推理侧的视觉编码器流水——训练侧同样成立。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("GPU 利用率低而 NCCL 很闲，常常是数据墙："),E("code",null,"nvidia-smi"),e(" 显示未满，剖析里 H2D 或 DataLoader wait 占步。")],-1)),(s(),o(n,null,{default:t(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22GPU%20%E5%88%A9%E7%94%A8%E7%8E%87%E4%BD%8E%EF%BC%8C%E5%90%9E%E5%90%90%E4%B8%8A%E4%B8%8D%E5%8E%BB%22%5D%20--%3E%20S%7B%22%E5%89%96%E6%9E%90%E9%87%8C%20H2D%20%2F%20DataLoader%20wait%20%E5%8D%A0%E5%A4%A7%E5%A4%B4%EF%BC%9F%22%7D%0A%20%20S%20--%3E%7C%E6%98%AF%7C%20DW%5B%22%E5%88%A4%E5%AE%9A%EF%BC%9A%E6%95%B0%E6%8D%AE%E5%A2%99%22%5D%0A%20%20S%20--%3E%7C%E5%90%A6%7C%20O%5B%22%E6%9F%A5%E8%AE%A1%E7%AE%97%E5%A2%99%E6%88%96%E9%80%9A%E4%BF%A1%E5%A2%99%22%5D%0A%20%20DW%20--%3E%20L1%7B%22%E5%AD%98%E5%82%A8%20GET%20%E5%90%9E%E5%90%90%E8%BE%BE%E6%A0%87%EF%BC%9F%22%7D%0A%20%20DW%20--%3E%20L2%7B%22%E4%B8%BB%E6%9C%BA%E8%A7%A3%E7%A0%81%E9%98%9F%E5%88%97%E5%A0%86%E7%A7%AF%EF%BC%9F%22%7D%0A%20%20DW%20--%3E%20L3%7B%22PCIe%20%2F%20H2D%20%E5%B8%A6%E5%AE%BD%E6%89%93%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20L1%20--%3E%7C%E5%90%A6%7C%20FIX1%5B%22%E5%8A%A0%E5%A4%A7%20shard%E3%80%81%E8%B5%B0%E5%AD%98%E5%82%A8%E5%B9%B3%E9%9D%A2%22%5D%0A%20%20L2%20--%3E%7C%E6%98%AF%7C%20FIX2%5B%22%E8%A7%A3%E7%A0%81%E8%BF%9B%E7%A8%8B%E6%B1%A0%E6%89%A9%E5%AE%B9%22%5D%0A%20%20L3%20--%3E%7C%E6%98%AF%7C%20FIX3%5B%22%E5%87%8F%E5%8D%8A%E7%B2%BE%E5%BA%A6%E4%BC%A0%E8%BE%93%20%2F%20%E9%87%8D%E7%BB%84%20batch%22%5D%0A%20%20O%20--%3E%20FIX4%5B%22%E6%8C%89%E5%AF%B9%E5%BA%94%E5%A2%99%E7%9A%84%E5%A4%84%E6%96%B9%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">这张图回答一个具体问题：吞吐异常时先判墙再开药。最容易做错的一步是「加卡」——数据墙下加 DP 度，等于让更多张卡同时去挤同一条存储出口，incast 更狠，吞吐不升反降，这就是「扩展性为负」的含义。</span></p><p>这与计算墙、通信墙的处方相反——加卡会让存储 incast 更狠，扩展性为负。先测每 rank 的样本/秒是否稳定，再加 DP 度。</p><p>确定性：固定 shard 映射与样本顺序，才能把一次坏 step 复现。流式系统用种子 + shard 列表实现；关掉它换吞吐时，要承认 debug 能力被卖掉。与分布式采样器重复样本或漏样本，是静默的数据 bug，比慢更危险。</p><p><span class="marginnote">重复数据与污染是评测课的对象。加载系统至少不要在 shuffle 里把同一 shard 分给两个 rank 而不记录。计数要对上：全局 batch × step = 看见的样本数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要让每个 step 打开新的小文件。<span class="marginnote">「每个 step 打开新文件」为什么危险：每次打开都有元数据查询和连接建立的开销，几千张卡 × 每秒几步，元数据服务器每秒要接几十万次请求，整条管道会被元数据而不是带宽拖垮。正确做法是 shard 内部顺序读，文件一次打开用很久。</span>不要在计算网上跑 PB 级扫描。不要假设「本地 SSD 一定更快」——若每次作业冷启动都要从对象存储灌满，第一小时会比直读还慢。检查点与数据流同盘时，做 QoS 或错开。</p><p>集群运行的下一层不是比特，是电与热：机架功率密度决定你到底能插多少张还在等数据的卡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据平面屋顶线是样本/秒；碎文件与启动 incast 把存储打进 \\(\\alpha\\) 区。</li><li>大数据 shard、主机解码重叠、存储平面与计算网分离。</li><li>加 DP 之前先确认加载跟得上，否则扩展为负。</li><li>打乱与复现是权衡；静默漏样本比慢更糟。</li><li>出处：WebDataset、Mosaic Streaming、DALI 一类流式加载实践。</li></ul>',9))])}const u=i(p,[["render",D]]);export{b as __pageData,u as default};
